App.ratingShort = function(c) {
	var r = Profile.R(c);
	if(r.games == 0) {
		return "sem pontuação";
	} else {
		return r.elo + (Profile.isProvisional(c) ? "?" : "");
	}
};
App.newGame = function() {
	var g = new Game();
	var o = App.opts;
	g.human = o.color == 0 ? Math.random() < 0.5 ? 1 : -1 : o.color;
	g.adaptive = o.opp == 0;
	g.level = o.opp == 0 ? 0 : o.opp;
	g.elo = g.adaptive ? Profile.d.adapt : Engine.LEVEL_ELO[g.level];
	g.oppName = g.adaptive ? "Mentor" : Engine.LEVEL_NAMES[g.level];
	g.cat = o.cat;
	g.coach = o.coach;
	g.process = o.process;
	if(g.cat == "rapid") {
		g.base = 600000;
		g.inc = 5000;
	}
	if(g.cat == "classic") {
		g.base = 1800000;
		g.inc = 20000;
	}
	g.clock = [g.base,g.base];
	g.pos = Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1");
	g.keys = [Engine.posKey(g.pos)];
	g.flip = g.human == -1;
	App.G = g;
	App.saveCurrent();
	App.showGame();
	if(g.pos.turn != g.human) {
		haxe_Timer.delay(App.cpuMove,400);
	} else {
		App.beginTurn();
	}
};
