Dna.importText = function(t) {
	var x = Dna.decode(t);
	if(x == null) {
		UiJs.toast("Não encontrei um DNA válido nesse texto.");
		return;
	}
	var nm = x.n != null && x.n != "" ? x.n : "Amigo";
	var id = nm.toLowerCase();
	var cl = Dna.clones();
	var c = null;
	var _g = 0;
	while(_g < cl.length) {
		var o = cl[_g];
		++_g;
		if(o.id == id) {
			c = o;
		}
	}
	if(c == null) {
		c = { id : id};
		cl.push(c);
	}
	c.n = nm;
	c.e = x.e;
	c.m = x.m;
	c.dna = x;
	c.t = new Date().getTime();
	Profile.save();
	UiJs.toast("Clone de " + nm + " importado.");
	Dna.clonePage(c);
};
