UiJs.lines = function(labels,series,lo,hi,unit,goal) {
	if(unit == null) {
		unit = "";
	}
	var n = labels.length;
	if(n == 0) {
		return;
	}
	var W = 400.0;
	var H = 210.0;
	var L = 40.0;
	var Rr = 22.0;
	var T = 14.0;
	var B = 30.0;
	var pw = W - L - Rr;
	var ph = H - T - B;
	var X = function(i) {
		if(n == 1) {
			return L + pw / 2;
		} else {
			return L + i * pw / (n - 1);
		}
	};
	var Y = function(v) {
		return T + ph - (v - lo) / (hi - lo) * ph;
	};
	var s_b = "";
	s_b += Std.string("<svg viewBox=\"0 0 " + W + " " + H + "\" class=\"lchart\" role=\"img\" aria-label=\"Evolução por mês\">");
	var _g = 0;
	while(_g < 5) {
		var k = _g++;
		var v = lo + (hi - lo) * k / 4;
		var y = Y(v);
		s_b += Std.string("<line x1=\"" + L + "\" y1=\"" + y + "\" x2=\"" + (W - Rr) + "\" y2=\"" + y + "\" stroke=\"#2b323c\" stroke-width=\"1\"/>");
		s_b += Std.string("<text x=\"" + (L - 6) + "\" y=\"" + (y + 4) + "\" text-anchor=\"end\" font-size=\"10.5\" fill=\"#7d8692\">" + Math.round(v) + unit + "</text>");
	}
	if(goal != null && goal > lo && goal < hi) {
		s_b += Std.string("<line x1=\"" + L + "\" y1=\"" + Y(goal) + "\" x2=\"" + (W - Rr) + "\" y2=\"" + Y(goal) + "\" stroke=\"#dcb55c\" stroke-width=\"1.2\" stroke-dasharray=\"5 5\" opacity=\".8\"/><text x=\"" + (W - Rr) + "\" y=\"" + (Y(goal) - 5) + "\" text-anchor=\"end\" font-size=\"10.5\" fill=\"#dcb55c\">meta " + Math.round(goal) + "</text>");
	}
	var step = n > 8 ? 2 : 1;
	var _g = 0;
	var _g1 = n;
	while(_g < _g1) {
		var i = _g++;
		if(i % step == 0 || i == n - 1) {
			s_b += Std.string("<text x=\"" + X(i) + "\" y=\"" + (H - 9) + "\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#98a1ab\">" + UiJs.esc(labels[i]) + "</text>");
		}
	}
	var _g = 0;
	while(_g < series.length) {
		var sr = series[_g];
		++_g;
		var vals = sr.vals;
		var c = sr.color;
		var seg = [];
		var segs = [];
		var _g1 = 0;
		var _g2 = n;
		while(_g1 < _g2) {
			var i = _g1++;
			var v = vals[i];
			if(v == null) {
				if(seg.length > 0) {
					segs.push(seg);
				}
				seg = [];
			} else {
				seg.push(X(i) + "," + Y(v));
			}
		}
		if(seg.length > 0) {
			segs.push(seg);
		}
		var _g3 = 0;
		while(_g3 < segs.length) {
			var q = segs[_g3];
			++_g3;
			if(q.length > 1) {
				s_b += Std.string("<polyline class=\"lpath\" points=\"" + q.join(" ") + "\" fill=\"none\" stroke=\"" + c + "\" stroke-width=\"2.6\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>");
			}
		}
		var _g4 = 0;
		var _g5 = n;
		while(_g4 < _g5) {
			var i1 = _g4++;
			var v1 = vals[i1];
			if(v1 != null) {
				s_b += Std.string("<circle cx=\"" + X(i1) + "\" cy=\"" + Y(v1) + "\" r=\"3.6\" fill=\"" + c + "\" stroke=\"#0b0d10\" stroke-width=\"1.2\"/>");
			}
		}
		var last = -1;
		var _g6 = 0;
		var _g7 = n;
		while(_g6 < _g7) {
			var i2 = _g6++;
			if(vals[i2] != null) {
				last = i2;
			}
		}
		if(last >= 0) {
			s_b += Std.string("<text x=\"" + Math.min(W - Rr,X(last) + 2) + "\" y=\"" + (Y(vals[last]) - 8) + "\" text-anchor=\"" + (last == n - 1 && n > 1 ? "end" : "middle") + "\" font-size=\"11\" font-weight=\"700\" fill=\"" + c + "\">" + Math.round(vals[last]) + "</text>");
		}
	}
	s_b += "</svg>";
	var w = UiJs.el("div","lchartw",UiJs.cur);
	w.innerHTML = s_b;
	if(series.length > 1) {
		var lg = UiJs.el("div","legend",UiJs.cur);
		var _g = 0;
		while(_g < series.length) {
			var sr = series[_g];
			++_g;
			var it = UiJs.el("span","lg",lg);
			var dot = UiJs.el("i","",it);
			dot.style.background = sr.color;
			it.appendChild(window.document.createTextNode(sr.name));
		}
	}
};
