Profile.combined = function() {
	var parts = [];
	var bestGame = 0;
	var games = 0;
	var _g = 0;
	var _g1 = Profile.CATS;
	while(_g < _g1.length) {
		var c = _g1[_g];
		++_g;
		var r = Profile.R(c);
		if(r.games >= 5 && r.elo > bestGame) {
			bestGame = r.elo;
		}
		games += r.games;
	}
	if(bestGame > 0) {
		parts.push(["Partidas",bestGame,0.5 * Math.min(1,games / 20)]);
	}
	if(Profile.d.pzN >= 10) {
		parts.push(["Quebra-cabeças",Profile.d.pzElo,0.25 * Math.min(1,Profile.d.pzN / 60)]);
	}
	var md = Profile.d.model;
	if(md.length > 0) {
		var s = 0.0;
		var n = 0;
		var i = md.length - 1;
		while(i >= 0 && n < 5) {
			s += md[i].perf;
			++n;
			--i;
		}
		parts.push(["Adivinhe o lance",s / n | 0,0.15 * Math.min(1,md.length / 5)]);
	}
	var pl = Profile.d.place;
	if(pl != null) {
		parts.push(["Teste de nivelamento",pl.est,parts.length == 0 ? 1.0 : 0.1]);
	}
	var sw = 0.0;
	var sv = 0.0;
	var _g = 0;
	while(_g < parts.length) {
		var p = parts[_g];
		++_g;
		sw += p[2];
		sv += p[1] * p[2];
	}
	var val = sw > 0 ? Math.round(sv / sw) | 0 : 0;
	return [val,parts];
};
