Study.placementResult = function(res) {
	var sum = 0.0;
	var n = 0;
	var sc = 0.0;
	var dims = { };
	var cnt = { };
	var fast = 0;
	var tot = 0;
	var _g = 0;
	while(_g < res.length) {
		var r = res[_g];
		++_g;
		var dm = r.dim;
		var a = Reflect.field(cnt,dm);
		if(a == null) {
			a = [0,0];
			cnt[dm] = a;
		}
		if(r.ok) {
			a[0]++;
		}
		a[1]++;
		sum += r.rating;
		sc += r.ok ? 1 : 0;
		++n;
		++tot;
		if(r.ok && r.ms <= 45000) {
			++fast;
		}
	}
	var _g = 0;
	var _g1 = Reflect.fields(cnt);
	while(_g < _g1.length) {
		var k = _g1[_g];
		++_g;
		var a = Reflect.field(cnt,k);
		dims[k] = Math.round(a[0] * 100 / a[1]) | 0;
	}
	dims["tempo"] = tot > 0 ? Math.round(fast * 100 / tot) | 0 : 0;
	var p = n > 0 ? sc / n : 0.0;
	p = Math.max(0.05,Math.min(0.95,p));
	var dp = -400 * Math.log(1 / p - 1) / Math.log(10);
	var est = n > 0 ? Math.round(sum / n + Math.max(-400,Math.min(400,dp))) | 0 : 800;
	est = Math.max(400,Math.min(2300,est)) | 0;
	var stp = est < 850 ? 1 : est < 1050 ? 2 : est < 1250 ? 3 : est < 1450 ? 4 : est < 1650 ? 5 : est < 1800 ? 6 : est < 1950 ? 7 : est < 2100 ? 8 : est < 2250 ? 9 : 10;
	return { day : Profile.today(), est : est, dims : dims, step : stp, ok : sc | 0, n : n};
};
