Online.resText = function(g) {
	var sc = g.res.score;
	if(sc >= 1) {
		return "vitória";
	} else if(sc <= 0) {
		return "derrota";
	} else {
		return "empate";
	}
};
Online.ago = function(t) {
	if(t == null) {
		return "";
	}
	var s = new Date().getTime() / 1000 - t;
	if(s < 90) {
		return "agora";
	}
	if(s < 3600) {
		return "há " + Math.round(s / 60) + " min";
	}
	if(s < 86400) {
		return "há " + Math.round(s / 3600) + " h";
	}
	return "há " + Math.round(s / 86400) + (Math.round(s / 86400) == 1 ? " dia" : " dias");
};
