History.card = function(id) {
	switch(id) {
	case "janggi":
		UiJs.gameCard(History.board9(true),"Janggi","Coreia · primo do xiangqi, sem rio e com as diagonais do palácio",Xiangqi.infoJanggi,function() {
			Xiangqi.quick(true);
		});
		break;
	case "moderno":
		UiJs.gameCard(History.board8("moderno"),"Xadrez moderno","Desde 1475 · a dama e o bispo com o alcance de hoje",App.setupGame,App.setupGame);
		break;
	case "xiangqi":
		UiJs.gameCard(History.board9(false),"Xiangqi","China · forma atual desde os séculos X a XIII · rio, palácio e canhões",Xiangqi.info,function() {
			Xiangqi.quick(false);
		});
		break;
	default:
		var g = Ancient.game(id);
		var sub;
		switch(id) {
		case "chaturanga":
			sub = "Índia · século VI · tabuleiro sem cores, o ashtapada";
			break;
		case "medieval":
			sub = "Europa · por volta de 1000 a 1475 · surge o tabuleiro bicolor";
			break;
		case "shatranj":
			sub = "Pérsia e mundo árabe · séculos VII a XV";
			break;
		case "sittuyin":
			sub = "Mianmar · soldados escalonados e promoção nas diagonais";
			break;
		default:
			sub = "Tailândia · o parente vivo mais próximo do chaturanga";
		}
		UiJs.gameCard(History.board8(id),g.name,sub,function() {
			Ancient.info(id);
		},function() {
			Ancient.quick(id);
		});
	}
};
History.wcard = function(id) {
	var x = World.get(id);
	if(x == null) {
		return;
	}
	UiJs.gameCard(World.thumb(id),x.name,x.era,function() {
		World.info(id);
	},function() {
		World.quick(id);
	});
};
History.treePlay = function(id) {
	switch(id) {
	case "eurogames":
		World.euro();
		break;
	case "janggi":
		Xiangqi.quick(true);
		break;
	case "moderno":
		App.setupGame();
		break;
	case "chaturanga":case "makruk":case "medieval":case "shatranj":case "sittuyin":
		Ancient.quick(id);
		break;
	case "xiangqi":
		Xiangqi.quick(false);
		break;
	default:
		if(World.get(id) != null) {
			World.quick(id);
		} else {
			World.info(id);
		}
	}
};
