Evo.monthly = function(cur) {
	var evo = Profile.d.evo;
	var ms_h = Object.create(null);
	var _g = 0;
	var _g1 = Reflect.fields(evo);
	while(_g < _g1.length) {
		var k = _g1[_g];
		++_g;
		ms_h[k] = true;
	}
	var _g = 0;
	var _g1 = Evo.hist();
	while(_g < _g1.length) {
		var x = _g1[_g];
		++_g;
		if(x.t != null) {
			ms_h[Profile.monthKey(x.t)] = true;
		}
	}
	var _g = [];
	var h = ms_h;
	var k_h = h;
	var k_keys = Object.keys(h);
	var k_length = k_keys.length;
	var k_current = 0;
	while(k_current < k_length) {
		var k = k_keys[k_current++];
		_g.push(k);
	}
	var keys = _g;
	keys.sort(function(a,b) {
		if(a < b) {
			return -1;
		} else {
			return 1;
		}
	});
	keys = keys.slice(-12);
	if(keys.length == 0) {
		UiJs.p("A linha do tempo começa com a sua primeira atividade registrada. Cada mês vira um ponto no gráfico.","muted");
		return;
	}
	var _g = [];
	var _g1 = 0;
	while(_g1 < keys.length) {
		var k = keys[_g1];
		++_g1;
		_g.push(Evo.MES[Std.parseInt(HxOverrides.substr(k,5,2)) - 1] + "/" + HxOverrides.substr(k,2,2));
	}
	var labels = _g;
	var elo = [];
	var tat = [];
	var fin = [];
	var abe = [];
	var pre = [];
	var _g = 0;
	while(_g < keys.length) {
		var k = keys[_g];
		++_g;
		var e = [Reflect.field(evo,k)];
		var ev = e[0] != null && e[0].e != null && e[0].e > 0 ? e[0].e : null;
		var last = null;
		var accS = 0.0;
		var accN = 0;
		var _g1 = 0;
		var _g2 = Evo.hist();
		while(_g1 < _g2.length) {
			var x = _g2[_g1];
			++_g1;
			if(x.t != null && Profile.monthKey(x.t) == k) {
				var rc = x.rc;
				if(rc != null) {
					last = rc[1];
				}
				if(x.acc != null) {
					accS += x.acc;
					++accN;
				}
			}
		}
		elo.push(ev != null ? ev : last);
		var dim = (function(e) {
			return function(f) {
				if(e[0] == null) {
					return null;
				}
				var v = Reflect.field(e[0],f);
				if(v == null || v < 0) {
					return null;
				} else {
					return v;
				}
			};
		})(e);
		tat.push(dim("tatica"));
		fin.push(dim("finais"));
		abe.push(dim("abertura"));
		pre.push(accN > 0 ? accS / accN : null);
	}
	var _g = [];
	var _g1 = 0;
	while(_g1 < elo.length) {
		var v = elo[_g1];
		++_g1;
		if(v != null) {
			_g.push(v);
		}
	}
	var ev = _g;
	if(ev.length > 0) {
		var lo = Math.floor((Lambda.fold(ev,Math.min,ev[0]) - 120) / 100) * 100;
		var hi = Math.ceil((Lambda.fold(ev,Math.max,ev[0]) + 120) / 100) * 100;
		if(hi - lo < 400) {
			hi = lo + 400;
		}
		UiJs.p("Elo estimado por mês","gold");
		var tmp = Math.max(0,lo);
		var tmp1 = cur > 0 ? Profile.nextGoal(cur) : null;
		UiJs.lines(labels,[{ name : "Elo estimado", color : "#f3d98c", vals : elo}],tmp,hi,"",tmp1);
	}
	var any = false;
	var a = tat;
	var _g = 0;
	while(_g < a.length) {
		var v = a[_g];
		++_g;
		if(v != null) {
			any = true;
		}
	}
	var a = fin;
	var _g = 0;
	while(_g < a.length) {
		var v = a[_g];
		++_g;
		if(v != null) {
			any = true;
		}
	}
	var a = abe;
	var _g = 0;
	while(_g < a.length) {
		var v = a[_g];
		++_g;
		if(v != null) {
			any = true;
		}
	}
	var a = pre;
	var _g = 0;
	while(_g < a.length) {
		var v = a[_g];
		++_g;
		if(v != null) {
			any = true;
		}
	}
	if(any) {
		UiJs.p("Habilidades por mês (% de acerto e precisão)","gold");
		UiJs.lines(labels,[{ name : "Tática", color : "#4b92d6", vals : tat},{ name : "Finais", color : "#4cb871", vals : fin},{ name : "Aberturas", color : "#e7a53c", vals : abe},{ name : "Precisão nas partidas", color : "#e3605a", vals : pre}],0,100,"");
	}
	if(keys.length == 1) {
		UiJs.p("Este é o primeiro mês registrado: as linhas aparecem a partir do segundo mês.","muted small");
	}
};
