V32.PERF={li:[['rapid','rápidas'],['classical','clássicas'],['blitz','blitz'],['bullet','bullet']],cc:[['chess_rapid','rápidas'],['chess_daily','por dia'],['chess_blitz','blitz'],['chess_bullet','bullet']]};
