/* Rota do Mestre v67 — Elo com credibilidade.
 * Problemas corrigidos:
 *  1) Nas 5 primeiras partidas a nota era a "performance" (força do adversário − 400 numa derrota): perder para o Difícil (1600) dava 1200.
 *     Agora a nota começa do seu Elo estimado (ou 800) e só se move pelo resultado (Profile.recordRated, Haxe).
 *  2) O Elo do Painel (combinado) podia subir depois de uma derrota: o teto subia a cada partida jogada e outras partes
 *     (precisão, pesos) mudavam junto. Agora:
 *     - o teto com poucas partidas cresce com vitórias (+25) e empates (+10), nunca com derrotas;
 *     - o número mostrado só muda de verdade numa partida valendo pontos: derrota sempre tira (no mínimo 10), vitória nunca tira;
 *       entre uma partida e outra ele pode cair (inatividade, ajustes), mas não sobe sozinho.
 *     - Nivelamento novo ou conta do Lichess confirmada recalculam o número.
 *  3) Notas antigas por categoria são recalculadas com a regra nova, refazendo as partidas guardadas no histórico.
 */
var V67={};
/* v69: nível escolhido na primeira vez (como no Chess.com) */
V67.LV={novo:{s:400,n:'Novo no xadrez',d:'Estou aprendendo as regras ou jogo muito pouco'},regras:{s:800,n:'Sei jogar',d:'Conheço as regras e jogo de vez em quando'},freq:{s:1200,n:'Jogo com frequência',d:'Jogo bastante e conheço táticas básicas'}};
V67.CAPN=30;
V67.start=function(){return 400;}; /* v70: começa sempre no mínimo */
V67.wins=function(){var w=0,dr=0,l=0;(Profile.CATS||['std','rapid','classic','online']).forEach(function(c){var r=Profile.d.r&&Profile.d.r[c];if(r){w+=r.w||0;dr+=r.d||0;l+=r.l||0;}});return {w:w,d:dr,l:l};};
V67.rated=function(){var n=0;(Profile.CATS||['std','rapid','classic','online']).forEach(function(c){var r=Profile.d.r&&Profile.d.r[c];if(r)n+=r.games||0;});return n;};
/* cálculo bruto (o da v29, com o teto por resultados em vez de por partidas jogadas) */
V67.raw=function(){
 var d=Profile.d,parts=[],bestGame=0,games=0,main=V67.main(),CS=Profile.CATS||['std','rapid','classic','online'];
 CS.forEach(function(c){var r=d.r&&d.r[c];if(!r)return;if(r.games>=5&&r.elo>bestGame)bestGame=r.elo;games+=r.games||0;});
 /* v69: treino nunca vale mais que 100 acima do que as partidas mostram (sem partidas: o nível escolhido) */
 var ref=main>0?main:V67.start(),ac=d.v29acc;
 if(ac&&ac.n>=3){var f=Math.min(1,ac.n/10),ap=Math.min(ac.perf,ref+100);parts.push(['Precisão nas partidas',ap,1.4*f*f]);games+=ac.imp||0;}
 if(main>0)parts.push([bestGame>0?'Partidas':'Partidas (provisória)',main,Math.max(0.5,0.7*Math.min(1,games/20))]);
 if(d.pzN>=20)parts.push(['Problemas',Math.min(V28.toGame(d.pzElo),ref+100),0.1*Math.min(1,d.pzN/100)]);
 var md=d.model||[];
 if(md.length>=3){var s=0,n=0;for(var i=md.length-1;i>=0&&n<5;i--){s+=md[i].perf;n++;}parts.push(['Adivinhe o lance',Math.min(V28.toGame(s/n),ref+100),0.05*Math.min(1,md.length/8)]);}
 var pl=d.place;
 if(pl&&pl.est){var pe=pl.method==='critico-v28'?pl.est:V28.toGame(pl.est);parts.push(['Nivelamento',pe,parts.length===0?1:0.15]);}
 try{if(typeof V32!=='undefined'&&V32.ext)V32.ext().forEach(function(x){parts.push(x);});}catch(e){}
 var sw=0,sv=0;parts.forEach(function(p){sw+=p[2];sv+=p[1]*p[2];});
 var val=sw>0?Math.round(sv/sw):0;
 /* v69: rigor máximo — até 30 partidas valendo pontos o número parte do nível escolhido, sobe só 12 por vitória e 4 por empate
    e nunca passa a sua melhor nota em partidas; depois disso, nunca passa 50 acima dela. Conta do Lichess confirmada libera. */
 var wr=V67.wins(),verified=typeof V32!=='undefined'&&V32.verified&&V32.verified();
 if(val>0&&!verified){
  if(V67.rated()<V67.CAPN){var cap=V67.start()+12*wr.w+4*wr.d;if(main>0)cap=Math.min(cap,main);
   if(val>cap){val=cap;parts.push(['Limite de iniciante ('+V67.start()+' + 12 por vitória)',cap,0]);}}
  else if(main>0&&val>main+50){val=main+50;parts.push(['Limite pelos resultados',val,0]);}
 }
 var out=parts.map(function(p){return [p[0],Math.round(p[1]),p[2]];});
 var dc=val>0?V29.decay():{amt:0};
 if(dc.amt>0){val=Math.max(100,val-dc.amt);out.push(['Inatividade',-dc.amt,0]);}
 return [val,out];
};
/* a sua nota principal em partidas: a maior entre as categorias jogadas */
V67.main=function(){var m=0;(Profile.CATS||['std','rapid','classic','online']).forEach(function(c){var r=Profile.d.r&&Profile.d.r[c];if(r&&r.games>0&&r.elo>m)m=r.elo;});return m;};

/* o que, se mudar, recalcula o número do zero (nivelamento novo, conta do Lichess confirmada) */
V67.sig=function(){var d=Profile.d,pl=d.place,li=null;try{li=V32.d().li;}catch(e){}return ['v70',pl&&(pl.t||pl.est)||0,li&&li.ver?(li.t||1):0].join('|');};
V67.state=function(){var d=Profile.d;if(!d.v67||typeof d.v67!=='object')d.v67={};return d.v67;};
Profile.combined=function(){
 var r=V67.raw(),st=V67.state(),sig=V67.sig();
 if(!(r[0]>0))return r;
 if(st.D==null||st.sig!==sig){st.D=r[0];st.sig=sig;st.n=V67.rated();try{Profile.save();}catch(e){}return r;}
 /* v69: entre partidas o número fica parado: treino não sobe nem desce; só a inatividade tira pontos */
 if(r[0]>st.D){r[1].push(['Treino a confirmar jogando','+'+(r[0]-st.D),0]);r[0]=st.D;}
 else if(r[0]<st.D){var ina=r[1].some(function(x){return x[0]==='Inatividade';});
  if(ina){st.D=r[0];try{Profile.save();}catch(e){}}else{r[1].push(['Ajuste a confirmar jogando',r[0]-st.D,0]);r[0]=st.D;}}
 return r;
};
/* cada partida valendo pontos decide para onde o número vai */
(function(){
 var o=Profile.recordRated;
 Profile.recordRated=function(cat,opp,score){
  var before=Profile.combined()[0];
  var rc=o.apply(this,arguments);
  try{
   var st=V67.state(),raw=V67.raw()[0],c=rc&&rc.length===2?rc[1]-rc[0]:0,D=before>0?before:raw,nd;
   /* v69: derrota tira no mínimo 15; vitória sobe no máximo 80% do que a categoria subiu; empate quase nunca sobe */
   if(!(before>0))nd=raw; /* primeira partida: o número nasce da própria partida */
   else if(score<=0)nd=Math.min(raw,D-Math.max(15,Math.abs(c)));
   else if(score>=1)nd=Math.max(D,Math.min(raw,D+Math.max(1,Math.round(c*0.8))));
   else nd=Math.min(raw,D+Math.max(-15,Math.min(4,c)));
   st.D=Math.max(100,Math.round(nd));st.sig=V67.sig();st.n=V67.rated();st.last={t:Date.now(),s:score,from:D,to:st.D,cat:cat};
   Profile.save();
  }catch(e){}
  return rc;
 };
})();
/* recalcula as notas por categoria com a regra nova, refazendo as partidas valendo pontos do histórico */
V67.migrate=function(){
 var d=Profile.d;if(!d||d.v67mig)return;
 var pl=d.place,start=d.v69lvl?V67.start():800;
 try{if(!d.v69lvl&&pl&&pl.est)start=Math.max(400,Math.min(2000,pl.method==='critico-v28'?pl.est:V28.toGame(pl.est)));}catch(e){}
 var hist=(d.hist||[]).slice().sort(function(a,b){return (a.t||0)-(b.t||0);});
 (Profile.CATS||['std','rapid','classic','online']).forEach(function(c){
  var r=d.r&&d.r[c];if(!r||!r.games)return;
  var hs=hist.filter(function(h){return h&&h.rated&&(h.cat||'std')===c&&h.oppElo>0&&h.res!=null;});
  if(hs.length!==r.games)return; /* histórico incompleto: mantém a nota */
  var t={elo:start,games:0},w=0,dr=0,l=0,peak=0;
  hs.forEach(function(h){t.elo=Profile.eloStep(t,h.oppElo,h.res);t.games++;if(h.res>=1)w++;else if(h.res<=0)l++;else dr++;if(t.games>=5&&t.elo>peak)peak=t.elo;});
  r.elo=t.elo;r.w=w;r.d=dr;r.l=l;r.peak=peak;r.v67=true;
 });
 d.v67mig=1;d.v67={};Profile.save();
};
if(typeof Profile!=='undefined'){try{if(Profile.d)V67.migrate();}catch(e){}
 var oL67=Profile.load;Profile.load=function(){var r=oL67.apply(this,arguments);try{V67.migrate();}catch(e){}return r;};}

/* ======================= v69 — rigor máximo =======================
 * Mais duro que Chess.com e Lichess (que usam Glicko, simétrico):
 *  - K menor (40 nas 5 primeiras, 24 até 30 partidas, 16 depois);
 *  - vitória vale metade (máx. +12 nas 5 primeiras, +8 depois; mín. +1);
 *  - derrota vale o dobro (mín. −20 nas 5 primeiras, −12 depois);
 *  - empate: ganho pela metade (máx. +4), perda em dobro; empate contra igual tira 4;
 *  - problemas (treino): ganho ×0,4, perda ×1,5.
 */
Profile.kOf=function(r){var g=r.games||0;return g<5?40:(g<30?24:((r.elo||0)>=2400?10:16));};
Profile.eloStep=function(r,opp,score){
 var k=Profile.kOf(r),e=Profile.expected(r.elo,opp),d=k*(score-e),prov=(r.games||0)<5;
 if(score<=0)d=Math.min(d*2,prov?-20:-12);
 else if(score>=1)d=Math.max(1,Math.min(d*0.5,prov?12:8));
 else d=d>0?Math.min(d*0.5,4):Math.min(d*2,-4);
 return Math.max(100,Math.round(r.elo+d));
};
Profile.startElo=function(){
 var s=V67.start();
 /* categoria nova começa na sua nota principal (nunca acima do nível + 12 por vitória) */
 var m=V67.main();if(m>0)return Math.max(100,Math.min(m,s+12*V67.wins().w));
 return s;
};
(function(){
 var o=Profile.recordPuzzle;
 Profile.recordPuzzle=function(){
  var b=Profile.d.pzElo,rr=o.apply(this,arguments);
  try{var dl=Profile.d.pzElo-b;if(dl>0)dl=Math.max(1,Math.round(dl*0.4));else if(dl<0)dl=Math.round(dl*1.5);
   Profile.d.pzElo=Math.max(100,b+dl);if(rr&&rr.length>1)rr[1]=Profile.d.pzElo;Profile.save();}catch(e){}
  return rr;
 };
})();
/* escolhe o nível e refaz as partidas do histórico a partir dele */
V67.setLevel=function(l){
 var d=Profile.d;if(!d||!V67.LV[l])return;
 d.v69lvl=l;d.v69t=Date.now();
 var start=V67.LV[l].s,hist=(d.hist||[]).slice().sort(function(a,b){return (a.t||0)-(b.t||0);});
 (Profile.CATS||['std','rapid','classic','online']).forEach(function(c){
  var r=d.r&&d.r[c];if(!r||!r.games)return;
  var hs=hist.filter(function(h){return h&&h.rated&&(h.cat||'std')===c&&h.oppElo>0&&h.res!=null;});
  if(hs.length===r.games){
   var t={elo:start,games:0},w=0,dr=0,ls=0,peak=0;
   hs.forEach(function(h){t.elo=Profile.eloStep(t,h.oppElo,h.res);t.games++;if(h.res>=1)w++;else if(h.res<=0)ls++;else dr++;if(t.games>=5&&t.elo>peak)peak=t.elo;});
   r.elo=t.elo;r.w=w;r.d=dr;r.l=ls;r.peak=peak;
  }else{ /* histórico incompleto: no máximo o nível + 12 por vitória */
   r.elo=Math.max(100,Math.min(r.elo||start,start+12*(r.w||0)));r.peak=Math.min(r.peak||0,r.elo);
  }
  r.v69=true;
 });
 d.v67={};d.v67mig=1;Profile.save();
};
/* v70: sem pergunta — todo perfil começa em 400 (o mínimo) e perfis antigos são refeitos uma vez a partir daí */
V67.force=function(){var d=Profile.d;if(!d||d.v70)return;V67.setLevel('novo');d.v70=1;Profile.save();};
if(typeof Profile!=='undefined'){try{if(Profile.d)V67.force();}catch(e){}
 var oL70=Profile.load;Profile.load=function(){var r=oL70.apply(this,arguments);try{V67.force();}catch(e){}return r;};}

/* Rota do Mestre v72 — "Seu maior adversário" com Lichess e Chess.com.
 * O jogo busca as suas partidas públicas de ~3 meses atrás (sem senha), monta o seu DNA daquela época
 * (aberturas que você jogava, ritmo, pressa, estilo, roque, trocas de dama e o nível pelo rating) e você joga contra ele.
 * As contas são as mesmas da Conta Google, do Painel e do "Analisar jogadas": ligou num lugar, vale em todos.
 */
var V72={};
V72.SITES={li:{n:'Lichess',pc:'♞',k:'lichess'},cc:{n:'Chess.com',pc:'♟',k:'chesscom'}};
V72.d=function(){var d=Profile.d;if(!d.v72)d.v72={};return d.v72;};
V72.user=function(s){var a=V32.acc();return s==='li'?a.lichess:a.chesscom;};
V72.mk=function(t){var d=new Date(t);return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2);};
V72.esc=V32.esc;

/* ---------- busca ---------- */
V72.fetchLi=function(u){
 var now=Date.now(),D=86400000;
 var get=function(since,until){return fetch('https://lichess.org/api/games/user/'+encodeURIComponent(u)+'?since='+since+'&until='+until+'&max=60&clocks=true&finished=true',{headers:{Accept:'application/x-chess-pgn'}})
  .then(function(r){if(r.status===404)throw new Error('usuário não encontrado no Lichess');if(r.status===429)throw new Error('o Lichess pediu para esperar um minuto');if(!r.ok)throw new Error('o Lichess respondeu '+r.status);return r.text();});};
 /* janela de 2 a 4 meses atrás; se tiver pouco, pega as 60 mais recentes antes de 1 mês atrás */
 return get(now-120*D,now-60*D).then(function(t){if(V26.splitPGN(t).length>=5)return t;return get(now-730*D,now-30*D);});
};
V72.fetchCc=function(u){
 return fetch('https://api.chess.com/pub/player/'+encodeURIComponent(V26.nk(u))+'/games/archives').then(function(r){if(r.status===404)throw new Error('usuário não encontrado no Chess.com');if(!r.ok)throw new Error('o Chess.com respondeu '+r.status);return r.json();})
 .then(function(j){
  var arc=(j&&j.archives)||[];if(!arc.length)throw new Error('nenhuma partida pública no Chess.com');
  var tk=V72.mk(Date.now()-90*86400000).replace('-','/'),old=arc.filter(function(a){return a.slice(-7)<=tk;});
  var pick=old.length?old.slice(-2):arc.slice(0,2);
  return Promise.all(pick.map(function(a){return fetch(a+'/pgn').then(function(r){return r.ok?r.text():'';});})).then(function(ts){return ts.join('\n\n');});
 });
};

/* ---------- DNA a partir das partidas ---------- */
V72.tc=function(tc){var m=/^(\d+)(?:\+(\d+))?/.exec(tc||'');return m?{base:+m[1],inc:+(m[2]||0)}:null;};
V72.build=function(site,user,text){
 var me=V26.nk(user),gs=[];
 V26.splitPGN(text).forEach(function(g){var r=V26.build(g);if(r.err)return;var c=V26.nk(r.w)===me?1:(V26.nk(r.b)===me?-1:0);if(!c||r.t0!==1)return;r.col=c;gs.push(r);});
 gs=gs.slice(-60);
 if(gs.length<5)return {err:gs.length?'só encontrei '+gs.length+' partida'+(gs.length>1?'s':'')+' sua'+(gs.length>1?'s':'')+' nessa época; preciso de pelo menos 5':'não encontrei partidas suas nessa época'};
 var rs=[],n=0,fast=0,timed=0,msS=0,msK=0,agg=0,ks=0,qs=0,cnS=0,cast=0,qx=0,dates=[],cnt={1:{},'-1':{}};
 V72._samp=V72._samp||{};V72._samp[site]=V72.sample(gs);
 gs.forEach(function(r){
  var el=r.col===1?r.we:r.be;if(el>0)rs.push(el);
  var t=V32.dateOf(r);if(t)dates.push(t);
  var tc=V72.tc(r.tc),inc=tc?tc.inc:0,castled=false;
  for(var k=0;k<r.u.length;k++){
   if((k%2===0?1:-1)!==r.col)continue;
   n++;var s=r.s[k]||'';
   if(/[x+#]/.test(s))agg++;
   if(!castled&&/^O-O/.test(s)){castled=true;cast++;cnS+=Math.floor(k/2)+1;if(/^O-O-O/.test(s))qs++;else ks++;}
   if(r.clk[k]!=null&&k>=2&&r.clk[k-2]!=null){var sp=(r.clk[k-2]-r.clk[k]+inc)*1000;if(sp>=0){timed++;msS+=sp;msK++;if(sp<5000)fast++;}}
  }
  var f=r.f[Math.min(40,r.f.length-1)]||'',bd=f.split(' ')[0];if(r.u.length>=24&&bd.indexOf('Q')<0&&bd.indexOf('q')<0)qx++;
  var key=Dna.enc(r.u.slice(0,12));cnt[r.col][key]=(cnt[r.col][key]||0)+1;
 });
 var lines=function(c){return Object.keys(cnt[c]).map(function(k){return [k,cnt[c][k]];}).sort(function(a,b){return b[1]-a[1];}).slice(0,12);};
 rs.sort(function(a,b){return a-b;});
 var med=rs.length?rs[Math.floor(rs.length/2)]:0,e=med?V32.toGame(site,med):600;
 /* erros: estimados pelo nível (o motor do jogo não analisou essas partidas lance a lance) */
 var x=Math.max(5,Math.min(26,26-(e-400)*0.012)),bl=Math.max(1,Math.min(9,9-(e-400)*0.005));
 dates.sort();var mid=dates.length?dates[Math.floor(dates.length/2)]:Date.now()-90*86400000;
 var pc=function(a,b){return b>0?Math.round(a*100/b):0;};
 return {v:1,src:site,m:V72.mk(mid),n:'Você no '+V72.SITES[site].n,e:e,site:med,
  ph:[Math.round(x*7)/10,Math.round(x*10)/10,Math.round(x*11.5)/10],bl:Math.round(bl*10)/10,
  fa:timed>=10?pc(fast,timed):null,fe:1.25,tl:1.3,ag:pc(agg,n),
  cs:cast*10>=gs.length*3?(qs>ks?'q':'k'):'',cn:cast?Math.round(cnS/cast):10,qx:pc(qx,gs.length),ms:msK?Math.round(msS/msK):15000,
  bp:null,bb:null,bq:null,bL:null,bw:null,vs:-1,ow:lines(1),ob:lines(-1),ax:null,g:gs.length,
  from:dates[0]||0,to:dates[dates.length-1]||0};
};
/* ---------- v73: erros de verdade ----------
   Sorteia lances seus das partidas importadas (até 40 por fase) e mede cada um com o Stockfish, em segundo plano:
   quanto a chance de vitória caiu em relação ao melhor lance. Erro = queda de 5 pontos ou mais (8 na abertura, onde aqui os lances de livro são perdoados); gafe = 15 ou mais
   (a mesma régua das partidas jogadas aqui). O resultado substitui a estimativa pelo rating. */
V72.phase=function(fen){var t=fen.split(' '),n=0,b=t[0];for(var i=0;i<b.length;i++)if('nbrqNBRQ'.indexOf(b[i])>=0)n++;return n<=6?2:((+t[5]||1)<=12?0:1);};
V72.sample=function(gs){
 var by=[[],[],[]];
 gs.forEach(function(r){for(var k=0;k<r.u.length;k++){if((k%2===0?1:-1)!==r.col)continue;if(k<8)continue;var f=r.f[k];if(!f)continue;by[V72.phase(f)].push({f:f,u:r.u[k]});}});
 var out=[];by.forEach(function(a,ph){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}a.slice(0,40).forEach(function(x){x.ph=ph;out.push(x);});});
 return out;
};
V72.measure=function(site){
 var smp=V72._samp&&V72._samp[site],slot=V72.d()[site];
 if(!smp||!smp.length||!slot||!slot.dna||typeof SF==='undefined'||SF.failed)return;
 var tok=(V72._mtok=V72._mtok||{});tok[site]=(tok[site]||0)+1;var my=tok[site];
 var cnt=[[0,0],[0,0],[0,0]],bl=0,n=0,i=0;
 slot.dna.meas=0;
 var fin=function(){
  var s2=V72.d()[site];if(!s2||!s2.dna||tok[site]!==my||n<30)return;
  var d=s2.dna,all=cnt[0][0]+cnt[1][0]+cnt[2][0],base=all/n;
  d.ph=cnt.map(function(c){return Math.round((c[1]>=8?c[0]/c[1]:base)*1000)/10;});
  d.bl=Math.round(bl*1000/n)/10;d.real=n;delete d.meas;Profile.save();
  try{if(UiJs.cur&&UiJs.cur.querySelector('.v72'))Dna.rival();}catch(e){}
 };
 var next=function(){
  if(tok[site]!==my)return;
  if(i>=smp.length){fin();return;}
  var x=smp[i++];
  SF.go({fen:x.f,depth:11,movetime:140},function(r){
   if(tok[site]!==my)return;
   if(!r||!r.lines.length||!r.best){if(SF.failed){fin();return;}next();return;}
   var bs=SF.score(r.lines[0]);
   var done=function(ms){var loss=Math.max(0,Coach.winPct(bs)-Coach.winPct(ms));n++;cnt[x.ph][1]++;if(loss>=(x.ph===0?8:5))cnt[x.ph][0]++;if(loss>=15)bl++;
    var s2=V72.d()[site];if(s2&&s2.dna&&s2.dna.real==null)s2.dna.meas=Math.round(100*i/smp.length);next();};
   if(x.u===r.best){done(bs);return;}
   SF.go({fen:x.f,depth:10,movetime:120,searchmoves:x.u},function(r2){if(tok[site]!==my)return;if(!r2||!r2.lines.length){next();return;}done(Math.min(bs,SF.score(r2.lines[0])));},true);
  },true);
 };
 next();
};
V72.importSite=function(site,btn){
 var u=V72.user(site);if(!u){UiJs.toast('Coloque o seu usuário do '+V72.SITES[site].n+' primeiro.');return;}
 if(V72.busy)return;V72.busy=site;
 if(btn){btn.disabled=true;btn.textContent='Buscando no '+V72.SITES[site].n+'…';}
 var f=site==='li'?V72.fetchLi:V72.fetchCc;
 f(u).then(function(text){
  var dna=V72.build(site,u,text);
  if(dna.err){V72.busy=null;UiJs.toast('No '+V72.SITES[site].n+', '+dna.err+'.');Dna.rival();return;}
  V72.d()[site]={dna:dna,t:Date.now(),user:u};Profile.save();
  /* as mesmas partidas entram no "Analisar jogadas" */
  try{V26.addName(u);V26.importText(text,site==='li'?'lichess':'chesscom',function(){});}catch(e){}
  V72.busy=null;UiJs.toast('Pronto: você de '+Dna.monthLabel(dna.m)+' no '+V72.SITES[site].n+' ('+dna.g+' partidas).');Dna.rival();
  try{V72.measure(site);}catch(e){}
 }).catch(function(e){V72.busy=null;UiJs.toast('Não consegui buscar: '+(e&&e.message||'sem conexão')+'.');Dna.rival();});
};
V72.play=function(site){
 var x=V72.d()[site];if(!x)return;var dna=x.dna;
 App.newGhostGame(dna,'Você · '+V72.SITES[site].n+' '+Dna.monthLabel(dna.m),'ext:'+site+':'+dna.m,Dna.duelColor||0);
};

/* ---------- bloco na tela "Seu maior adversário" ---------- */
V72.block=function(box){
 var keep=UiJs.cur;UiJs.cur=box;
 var hd=UiJs.el('div','v72-hd',box);hd.innerHTML='<span class="v72-li">♞ Lichess</span><i>·</i><span class="v72-cc">♟ Chess.com</span>';
 UiJs.el('div','v72-tt',box,'Você de 3 meses atrás nesses sites');
 UiJs.p('Importe as suas partidas de uns 3 meses atrás e enfrente o você daquela época: as mesmas aberturas, o mesmo ritmo, o mesmo estilo e o nível do seu rating de então. Não precisa ter jogado aqui.','v72-tx');
 var any=false;
 ['li','cc'].forEach(function(s){
  var u=V72.user(s);if(!u)return;any=true;
  var x=V72.d()[s],ok=x&&V26.nk(x.user)===V26.nk(u),S=V72.SITES[s];
  var row=UiJs.el('div','v72-row v72-'+s,box);
  var top=UiJs.el('div','v72-rt',row);top.innerHTML='<b>'+S.pc+' '+S.n+'</b><span>@'+V72.esc(u)+'</span>';
  if(ok){
   var d=x.dna,ln=UiJs.el('div','v72-in',row);
   ln.innerHTML='<b>'+Dna.monthLabel(d.m)+'</b> · '+d.g+' partidas · rating '+d.site+' no '+S.n+' → nível <b>'+d.e+'</b> aqui · placar '+Dna.scoreTxt('ext:'+s+':'+d.m);
   var ds=Dna.describe(d,'você').filter(function(t){return !/^Erra |^Gafes|Pontos cegos|^Sem pontos cegos/.test(t);}).slice(0,3);
   /* v73: erros medidos de verdade pelo Stockfish (ou a estimativa, enquanto a medição não termina) */
   if(d.real)ds.unshift('Erros medidos em '+d.real+' lances seus: '+d.ph[0]+' a cada 100 na abertura, '+d.ph[1]+' no meio-jogo, '+d.ph[2]+' no final; gafes: '+d.bl+'.');
   else ds.push(d.meas!=null?'Medindo os seus erros de verdade… '+d.meas+'%':'Erros estimados pelo rating (toque em Atualizar para medir de verdade).');
   if(ds.length){var ul=UiJs.el('ul','v72-ds',row);ds.forEach(function(t){UiJs.el('li','',ul,t);});}
   var bs=UiJs.el('div','v72-bs',row);
   var b1=UiJs.el('button','btn pri',bs,'Desafiar você de '+Dna.monthLabel(d.m));b1.onclick=function(){V72.play(s);};
   var b2=UiJs.el('button','btn',bs,'Atualizar');b2.onclick=function(){V72.importSite(s,b2);};
  }else{
   var bs2=UiJs.el('div','v72-bs',row);
   var b=UiJs.el('button','btn pri',bs2,V72.busy===s?'Buscando no '+S.n+'…':'Importar minhas partidas de 3 meses atrás');b.disabled=V72.busy===s;b.onclick=function(){V72.importSite(s,b);};
  }
 });
 /* campos de integração: os mesmos de todos os menus */
 var fw=UiJs.el('div','v72-form',box);
 if(any){var tg=UiJs.el('button','v72-tog',fw,'Contas do Lichess e do Chess.com ›');var inner=UiJs.el('div','v72-inner',fw);inner.style.display='none';
  tg.onclick=function(){var o=inner.style.display==='none';inner.style.display=o?'':'none';tg.textContent='Contas do Lichess e do Chess.com '+(o?'⌄':'›');if(o&&!inner.firstChild)V32.chessForm(inner);};}
 else{UiJs.el('div','p v72-tx v72-hint',fw,'Só o nome de usuário, sem senha. Ligou aqui, vale no jogo inteiro: Painel, Analisar jogadas e Conta.');V32.chessForm(fw);}
 UiJs.p('As aberturas, a pressa, o estilo e o roque vêm das suas partidas de verdade. Os erros são medidos pelo Stockfish numa amostra de lances seus (leva cerca de um minuto, em segundo plano); até terminar, vale uma estimativa pelo rating da época. O duelo não muda o seu Elo.','muted small');
 UiJs.cur=keep;
};
(function(){
 var o=Dna.rival;
 Dna.rival=function(){
  var r=o.apply(this,arguments);
  try{var page=UiJs.cur,first=null;
   [].slice.call(page.querySelectorAll('.p')).some(function(p){if(/Você contra você de 3 meses/.test(p.textContent)){first=p;return true;}return false;});
   var box=document.createElement('div');box.className='v72';V72.block(box);
   /* logo abaixo da explicação, antes de "Meu DNA Enxadrista" */
   if(first&&first.parentNode)first.parentNode.insertBefore(box,first.nextSibling);else page.insertBefore(box,page.firstChild);
   /* sem 20 partidas aqui: o aviso vira alternativa, não bloqueio */
   [].slice.call(page.querySelectorAll('.p')).forEach(function(p){if(/exige 20 partidas analisadas/.test(p.textContent)){var m=/\((\d+)\/20/.exec(p.textContent);p.textContent='Ou crie o fantasma deste jogo: jogue 20 partidas aqui'+(m?' ('+m[1]+'/20 registradas)':'')+' e ele aparece abaixo.';p.className='v72-alt';}});
   /* quando o usuário muda nos campos, a tela se refaz */
   box.addEventListener('change',function(ev){if(ev.target&&ev.target.classList.contains('fi'))setTimeout(function(){if(document.body.contains(box))Dna.rival();},60);});
  }catch(e){}
  return r;
 };
})();

/* ======================= v73 — Stockfish joga nos níveis mais altos =======================
 * Níveis 5 (Grande Mestre, força limitada) e 6 (Stockfish, força máxima) são jogados pelo Stockfish que já vem no jogo.
 * Os lances de abertura continuam vindo do livro de mestres (variedade). O Stockfish recebe a partida inteira,
 * para enxergar repetições. Se ele não carregar neste aparelho, joga o motor do jogo e a tela avisa.
 */
var V73={};
/* 2900 na escala do próprio Stockfish equivale a cerca de 2500 na escala dos níveis do jogo (medido contra o nível Mestre) */
V73.LV={5:{elo:2900,ms:500},6:{elo:0,ms:900}};
V73.warned=false;
V73.posCmd=function(q){
 try{
  if(q.ucis&&q.ucis.length){
   var p=Engine.posFromFEN(q.start||'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'),ok=true;
   for(var i=0;i<q.ucis.length;i++){var m=Engine.uciToMove(p,q.ucis[i]);if(m<0){ok=false;break;}Engine.makeMove(p,m);}
   if(ok&&Engine.toFEN(p).split(' ').slice(0,4).join(' ')===q.fen.split(' ').slice(0,4).join(' '))
    return 'position '+(q.start?'fen '+q.start:'startpos')+' moves '+q.ucis.join(' ');
  }
 }catch(e){}
 return 'position fen '+q.fen;
};
(function(){
 var prev=Think.run;
 Think.run=function(q,cb){
  var cfg=q&&q.cmd==='cpu'&&q.elo==null?V73.LV[q.level]:null;
  if(!cfg||typeof SF==='undefined'||SF.failed){
   if(cfg&&!V73.warned){V73.warned=true;try{UiJs.toast('O Stockfish não carregou neste aparelho: este nível joga com o motor do jogo, que é mais fraco.');}catch(e){}}
   return prev(q,cb);
  }
  var qb={};for(var k in q)qb[k]=q[k];qb.bookOnly=true;
  prev(qb,function(r){
   if(r&&r.uci){cb(r);return;}
   Think.busy++;
   SF.go({fen:q.fen,pos:V73.posCmd(q),movetime:cfg.ms,elo:cfg.elo,play:true},function(res){
    Think.busy--;
    if(!res||!res.best){
     if(!V73.warned){V73.warned=true;try{UiJs.toast('O Stockfish não carregou neste aparelho: este nível joga com o motor do jogo, que é mais fraco.');}catch(e){}}
     prev(q,cb);return;
    }
    var sc=res.lines&&res.lines[0]?SF.score(res.lines[0]):null;
    prev({cmd:'cpunote',fen:q.fen,uci:res.best,human:q.human,score:sc},cb);
   });
  });
 };
})();

